function draw({board,width,height,progress,params}) {
 const P=VisualBook.palette,mobile=width<500,eta=params.eta,gamma=params.gamma;
 const gradient=([x,y])=>[0.2*x,4*y],opts={eta,rho:gamma,epsilon:1e-6,steps:20};
 const rms=VisualBook.trace('rmsprop',gradient,[-5,-2],opts),ada=VisualBook.trace('adagrad',gradient,[-5,-2],opts);
 const current=VisualBook.interpolateTrace(rms,progress),other=VisualBook.interpolateTrace(ada,progress);
 const f=board.axes('trajectory-axes',{xDomain:[-5.8,1.2],yDomain:[-2.4,2.4],equalUnits:true,xLabel:'参数 x₁',yLabel:'参数 x₂',box:mobile?[48,72,width-22,height-155]:[48,72,width*0.63,height-65],grid:true});
 board.line('legend-rms',48,44,67,44,P.blue,3);board.text('legend-rms-label','RMSProp',74,49,{size:13,color:P.blue});board.line('legend-ada',180,44,199,44,P.orange,2);board.text('legend-ada-label','Adagrad',206,49,{size:13,color:P.orange});
 for(const level of [0.2,1,3,6,10]) {let seg=[],part=0;const flush=()=>{if(seg.length>1)board.curve('contour-'+level+'-'+part++,f,seg,{color:P.faint,width:1});seg=[];};for(let i=0;i<=180;i++){const a=i/180*2*Math.PI,x=Math.sqrt(level/0.1)*Math.cos(a),y=Math.sqrt(level/2)*Math.sin(a);if(x>=-5.8&&x<=1.2&&y>=-2.4&&y<=2.4)seg.push([x,y]);else flush();}flush();}
 const prefix=(tr,cur)=>[...tr.slice(0,Math.floor(cur.index)+1).map(p=>p.theta),cur.theta];
 board.curve('rms-full',f,rms.map(p=>p.theta),{color:P.blue,width:1.5,opacity:0.16});board.curve('ada-full',f,ada.map(p=>p.theta),{color:P.orange,width:1.5,opacity:0.16});board.curve('rms-prefix',f,prefix(rms,current),{color:P.blue,width:3});board.curve('ada-prefix',f,prefix(ada,other),{color:P.orange,width:2});board.circle('origin',f.x(0),f.y(0),2.5,P.ink);board.circle('rms-current',f.x(current.theta[0]),f.y(current.theta[1]),5,P.blue);board.circle('ada-current',f.x(other.theta[0]),f.y(other.theta[1]),4,P.orange);
 const tx=mobile?48:width*0.68,ty=mobile?height-78:92,pair=a=>'('+a[0].toFixed(2)+', '+a[1].toFixed(2)+')';board.text('iteration','第 '+current.index.toFixed(1)+' / 20 步',tx,ty,{size:14,color:P.ink});board.text('rms-readout','RMSProp '+pair(current.theta),tx,ty+25,{size:13,color:P.blue});board.text('ada-readout','Adagrad '+pair(other.theta),tx,ty+48,{size:13,color:P.orange});
 if(mobile){board.text('mobile-first-scale','首步 η/√(s+ε) = '+pair(rms[1].square.map(s=>eta/Math.sqrt(s+1e-6))),48,height-8,{size:12,color:P.muted});} if(!mobile){const first=rms[1];board.text('first-scaling-title','首步缩放 η / √(s + ε)',tx,ty+99,{size:12,color:P.muted});board.text('first-scaling',pair(first.square.map(s=>eta/Math.sqrt(s+1e-6))),tx,ty+123,{size:14,color:P.ink});board.text('first-delta-title','首步位移 Δx',tx,ty+156,{size:12,color:P.muted});board.text('first-delta',pair(first.theta.map((v,i)=>v-[-5,-2][i])),tx,ty+180,{size:14,color:P.blue});}
 return {objective:{a:0.1,b:2},eta,gamma,epsilon:1e-6,steps:20,rmsTrace:rms,adagradTrace:ada,current,comparison:other,firstScale:rms[1].square.map(s=>eta/Math.sqrt(s+1e-6)),firstDisplacement:rms[1].theta.map((v,i)=>v-[-5,-2][i]),unitX:f.unitX,unitY:f.unitY,interpolation:'between discrete updates only'};
}
